-- =============================================================================
-- 2. Starter recipe collection (112 recipes written for this project, 78 of them Indian)
-- Diet labels here were written for this project and checked by hand.
--   vegetarian = no meat, fish or eggs · eggetarian = vegetarian plus eggs
--   non_veg = eggs and chicken are fine, but no other meat or fish
--   gluten_free treats hing (asafoetida) as containing gluten: most hing is mixed with wheat flour
-- Recipes you add are labeled by AI (see 04_ai_tags.sql), which can also compare AI labels with these.
-- =============================================================================
INSERT INTO recipes (title, cuisine, minutes, servings, ingredients, steps,
                     vegetarian, eggetarian, non_veg, gluten_free, dairy_free, nut_free,
                     tagged_by, source, search_text)
VALUES
  ('Garlicky Spinach Scrambled Eggs', 'American', 10, 2, ARRAY['eggs', 'baby spinach', 'garlic', 'butter', 'salt', 'black pepper'],
   'Melt the butter in a pan over medium heat and soften the sliced garlic for a minute. Add the spinach and stir until just wilted. Pour in the beaten eggs, season, and stir gently until softly set.',
   false, true, true, true, false, true, 'starter', 'starter',
   'Garlicky Spinach Scrambled Eggs. American dish, 10 minutes. Ingredients: eggs, baby spinach, garlic, butter, salt, black pepper. Melt the butter in a pan over medium heat and soften the sliced garlic for a minute. Add the spinach and stir until just wilted. Pour in the beaten eggs, season, and stir gently until softly set.'),
  ('Chickpea and Spinach Curry', 'Indian', 30, 4, ARRAY['canned chickpeas', 'baby spinach', 'onion', 'garlic', 'canned tomatoes', 'coconut milk', 'curry powder', 'basmati rice'],
   'Start the rice. Fry the diced onion until golden, add garlic and curry powder for a minute, then the tomatoes and coconut milk. Add the drained chickpeas and simmer 15 minutes. Stir in the spinach until wilted and serve over rice.',
   true, true, true, true, true, true, 'starter', 'starter',
   'Chickpea and Spinach Curry. Indian dish, 30 minutes. Ingredients: canned chickpeas, baby spinach, onion, garlic, canned tomatoes, coconut milk, curry powder, basmati rice. Start the rice. Fry the diced onion until golden, add garlic and curry powder for a minute, then the tomatoes and coconut milk. Add the drained chickpeas and simmer 15 minutes. Stir in the spinach until wilted and serve over rice.'),
  ('Lemon Herb Chicken Thighs', 'Mediterranean', 35, 4, ARRAY['chicken thighs', 'lemon', 'garlic', 'olive oil', 'oregano', 'salt', 'black pepper'],
   'Toss the chicken with olive oil, lemon zest and juice, crushed garlic, oregano, salt and pepper. Roast skin side up at 425°F (220°C) for about 30 minutes, until golden and cooked through. Rest 5 minutes before serving.',
   false, false, true, true, true, true, 'starter', 'starter',
   'Lemon Herb Chicken Thighs. Mediterranean dish, 35 minutes. Ingredients: chicken thighs, lemon, garlic, olive oil, oregano, salt, black pepper. Toss the chicken with olive oil, lemon zest and juice, crushed garlic, oregano, salt and pepper. Roast skin side up at 425°F (220°C) for about 30 minutes, until golden and cooked through. Rest 5 minutes before serving.'),
  ('Blistered Cherry Tomato Pasta', 'Italian', 20, 2, ARRAY['pasta', 'cherry tomatoes', 'garlic', 'olive oil', 'basil', 'parmesan'],
   'Boil the pasta. Meanwhile, cook the tomatoes in olive oil over high heat until they burst, then add sliced garlic. Toss with the drained pasta, a splash of pasta water, torn basil and grated parmesan.',
   true, true, true, false, false, true, 'starter', 'starter',
   'Blistered Cherry Tomato Pasta. Italian dish, 20 minutes. Ingredients: pasta, cherry tomatoes, garlic, olive oil, basil, parmesan. Boil the pasta. Meanwhile, cook the tomatoes in olive oil over high heat until they burst, then add sliced garlic. Toss with the drained pasta, a splash of pasta water, torn basil and grated parmesan.'),
  ('Chicken Fajita Wraps', 'Mexican', 25, 4, ARRAY['chicken thighs', 'bell peppers', 'onion', 'tortillas', 'cumin', 'paprika', 'lemon', 'cilantro'],
   'Slice the chicken, peppers and onion into strips. Season with cumin and paprika and cook in a hot pan until charred and cooked through. Squeeze over lemon, then serve in warm tortillas with cilantro.',
   false, false, true, false, true, true, 'starter', 'starter',
   'Chicken Fajita Wraps. Mexican dish, 25 minutes. Ingredients: chicken thighs, bell peppers, onion, tortillas, cumin, paprika, lemon, cilantro. Slice the chicken, peppers and onion into strips. Season with cumin and paprika and cook in a hot pan until charred and cooked through. Squeeze over lemon, then serve in warm tortillas with cilantro.'),
  ('Veggie Fried Rice', 'Chinese', 20, 2, ARRAY['basmati rice', 'eggs', 'frozen peas', 'carrots', 'green onion', 'soy sauce'],
   'Use rice cooked earlier, ideally cold. Scramble the eggs in a hot oiled pan and set aside. Stir-fry diced carrot and peas, add the rice and fry until hot, then return the eggs with soy sauce and sliced green onion.',
   false, true, true, false, true, true, 'starter', 'starter',
   'Veggie Fried Rice. Chinese dish, 20 minutes. Ingredients: basmati rice, eggs, frozen peas, carrots, green onion, soy sauce. Use rice cooked earlier, ideally cold. Scramble the eggs in a hot oiled pan and set aside. Stir-fry diced carrot and peas, add the rice and fry until hot, then return the eggs with soy sauce and sliced green onion.'),
  ('Banana Peanut Butter Overnight Oats', 'Breakfast', 5, 1, ARRAY['oats', 'milk', 'bananas', 'peanut butter', 'honey'],
   'Stir the oats, milk, half a mashed banana and a spoon of peanut butter together in a jar. Refrigerate overnight. Top with the rest of the banana and a drizzle of honey.',
   true, true, true, false, false, false, 'starter', 'starter',
   'Banana Peanut Butter Overnight Oats. Breakfast dish, 5 minutes. Ingredients: oats, milk, bananas, peanut butter, honey. Stir the oats, milk, half a mashed banana and a spoon of peanut butter together in a jar. Refrigerate overnight. Top with the rest of the banana and a drizzle of honey.'),
  ('Greek Yogurt Breakfast Bowl', 'Breakfast', 5, 1, ARRAY['greek yogurt', 'oats', 'berries', 'honey'],
   'Spoon the yogurt into a bowl, then top with oats, fresh berries and a drizzle of honey.',
   true, true, true, false, false, true, 'starter', 'starter',
   'Greek Yogurt Breakfast Bowl. Breakfast dish, 5 minutes. Ingredients: greek yogurt, oats, berries, honey. Spoon the yogurt into a bowl, then top with oats, fresh berries and a drizzle of honey.'),
  ('Cheesy Black Bean Quesadillas', 'Mexican', 15, 2, ARRAY['tortillas', 'canned black beans', 'cheddar cheese', 'bell peppers', 'salsa'],
   'Mash half the beans lightly. Fill each tortilla with beans, diced pepper and cheddar, then fold. Cook in a dry pan until crisp on both sides and the cheese melts. Serve with salsa.',
   true, true, true, false, false, true, 'starter', 'starter',
   'Cheesy Black Bean Quesadillas. Mexican dish, 15 minutes. Ingredients: tortillas, canned black beans, cheddar cheese, bell peppers, salsa. Mash half the beans lightly. Fill each tortilla with beans, diced pepper and cheddar, then fold. Cook in a dry pan until crisp on both sides and the cheese melts. Serve with salsa.'),
  ('Creamy Tomato Soup', 'American', 30, 4, ARRAY['canned tomatoes', 'onion', 'garlic', 'vegetable broth', 'heavy cream', 'butter'],
   'Soften the onion and garlic in butter. Add the tomatoes and broth and simmer 20 minutes. Blend until smooth, then stir in the cream and season to taste.',
   true, true, true, true, false, true, 'starter', 'starter',
   'Creamy Tomato Soup. American dish, 30 minutes. Ingredients: canned tomatoes, onion, garlic, vegetable broth, heavy cream, butter. Soften the onion and garlic in butter. Add the tomatoes and broth and simmer 20 minutes. Blend until smooth, then stir in the cream and season to taste.'),
  ('Pea and Mint Risotto', 'Italian', 35, 3, ARRAY['arborio rice', 'frozen peas', 'onion', 'vegetable broth', 'parmesan', 'butter', 'mint'],
   'Soften the onion in butter, add the rice and stir for a minute. Add hot broth a ladle at a time, stirring, for about 20 minutes. Stir in the peas, parmesan and chopped mint in the last few minutes.',
   true, true, true, true, false, true, 'starter', 'starter',
   'Pea and Mint Risotto. Italian dish, 35 minutes. Ingredients: arborio rice, frozen peas, onion, vegetable broth, parmesan, butter, mint. Soften the onion in butter, add the rice and stir for a minute. Add hot broth a ladle at a time, stirring, for about 20 minutes. Stir in the peas, parmesan and chopped mint in the last few minutes.'),
  ('Two-Ingredient Banana Pancakes', 'Breakfast', 15, 1, ARRAY['bananas', 'eggs', 'cinnamon'],
   'Mash a ripe banana and whisk with two eggs and a pinch of cinnamon. Cook small pancakes in a lightly oiled pan over medium-low heat, flipping once.',
   false, true, true, true, true, true, 'starter', 'starter',
   'Two-Ingredient Banana Pancakes. Breakfast dish, 15 minutes. Ingredients: bananas, eggs, cinnamon. Mash a ripe banana and whisk with two eggs and a pinch of cinnamon. Cook small pancakes in a lightly oiled pan over medium-low heat, flipping once.'),
  ('Red Lentil Soup', 'Middle Eastern', 35, 4, ARRAY['red lentils', 'onion', 'carrots', 'garlic', 'cumin', 'vegetable broth', 'lemon'],
   'Soften the onion, carrot and garlic. Add cumin, the rinsed lentils and broth, and simmer 25 minutes until the lentils fall apart. Blend partly, then finish with lemon juice.',
   true, true, true, true, true, true, 'starter', 'starter',
   'Red Lentil Soup. Middle Eastern dish, 35 minutes. Ingredients: red lentils, onion, carrots, garlic, cumin, vegetable broth, lemon. Soften the onion, carrot and garlic. Add cumin, the rinsed lentils and broth, and simmer 25 minutes until the lentils fall apart. Blend partly, then finish with lemon juice.'),
  ('Black Bean Stuffed Peppers', 'Tex-Mex', 40, 4, ARRAY['bell peppers', 'basmati rice', 'canned black beans', 'corn', 'cheddar cheese', 'salsa'],
   'Halve and seed the peppers. Mix cooked rice, beans, corn and salsa, then fill the peppers. Top with cheddar and bake at 400°F (200°C) for about 25 minutes.',
   true, true, true, true, false, true, 'starter', 'starter',
   'Black Bean Stuffed Peppers. Tex-Mex dish, 40 minutes. Ingredients: bell peppers, basmati rice, canned black beans, corn, cheddar cheese, salsa. Halve and seed the peppers. Mix cooked rice, beans, corn and salsa, then fill the peppers. Top with cheddar and bake at 400°F (200°C) for about 25 minutes.'),
  ('Sesame Peanut Noodles', 'Thai-inspired', 20, 2, ARRAY['noodles', 'peanut butter', 'soy sauce', 'garlic', 'lemon', 'cucumber', 'green onion'],
   'Cook the noodles. Whisk peanut butter, soy sauce, grated garlic, lemon juice and a splash of hot water into a sauce. Toss with the noodles, then top with sliced cucumber and green onion.',
   true, true, true, false, true, false, 'starter', 'starter',
   'Sesame Peanut Noodles. Thai-inspired dish, 20 minutes. Ingredients: noodles, peanut butter, soy sauce, garlic, lemon, cucumber, green onion. Cook the noodles. Whisk peanut butter, soy sauce, grated garlic, lemon juice and a splash of hot water into a sauce. Toss with the noodles, then top with sliced cucumber and green onion.'),
  ('Shakshuka', 'North African', 25, 2, ARRAY['eggs', 'canned tomatoes', 'onion', 'bell peppers', 'garlic', 'paprika', 'cumin'],
   'Cook the onion and pepper until soft, add garlic and spices, then the tomatoes, and simmer 10 minutes. Make wells, crack in the eggs, cover and cook until the whites set.',
   false, true, true, true, true, true, 'starter', 'starter',
   'Shakshuka. North African dish, 25 minutes. Ingredients: eggs, canned tomatoes, onion, bell peppers, garlic, paprika, cumin. Cook the onion and pepper until soft, add garlic and spices, then the tomatoes, and simmer 10 minutes. Make wells, crack in the eggs, cover and cook until the whites set.'),
  ('Chicken and Rice Soup', 'American', 45, 4, ARRAY['chicken thighs', 'basmati rice', 'carrots', 'celery', 'onion', 'chicken broth'],
   'Simmer the chicken in the broth for 20 minutes, then remove and shred. Add diced onion, carrot, celery and the rice and cook 15 minutes. Return the chicken and season.',
   false, false, true, true, true, true, 'starter', 'starter',
   'Chicken and Rice Soup. American dish, 45 minutes. Ingredients: chicken thighs, basmati rice, carrots, celery, onion, chicken broth. Simmer the chicken in the broth for 20 minutes, then remove and shred. Add diced onion, carrot, celery and the rice and cook 15 minutes. Return the chicken and season.'),
  ('Caprese Salad', 'Italian', 10, 2, ARRAY['tomatoes', 'mozzarella', 'basil', 'olive oil', 'balsamic vinegar'],
   'Slice the tomatoes and mozzarella and arrange them overlapping with basil leaves. Drizzle with olive oil and balsamic, then season with salt and pepper.',
