  ('Vegetable Upma', 'South Indian', 25, 2, ARRAY['semolina (rava)', 'onion', 'carrots', 'green beans', 'peas (matar)', 'mustard seeds (rai)', 'curry leaves (kadi patta)', 'green chilies (hari mirch)'],
