  ('Broken Wheat Vegetable Upma', 'Indian', 30, 2, ARRAY['broken wheat (dalia)', 'onion', 'carrots', 'green beans', 'peas (matar)', 'mustard seeds (rai)', 'curry leaves (kadi patta)', 'green chilies (hari mirch)'],
