  ('Sambar', 'South Indian', 40, 4, ARRAY['toor dal (arhar)', 'drumsticks', 'pumpkin (kaddu)', 'tomatoes', 'tamarind (imli)', 'sambar powder', 'mustard seeds (rai)', 'curry leaves (kadi patta)', 'asafoetida (hing)'],
